    ; === Runtime routines ===

_mul16:
    LDA $B4
    STA $B2
    LDA $B5
    STA $B3
    ; Save lhs since we shift multiplicand
    LDA $B0
    STA $B6
    LDA $B1
    STA $B7
    ; Determine sign
    LDA #$00
    STA $B8         ; sign flag
    LDA $B7
    BPL .mul_op1_pos
    ; Negate operand1
    LDA $B6 : EOR #$FF : STA $B6
    LDA $B7 : EOR #$FF : STA $B7
    INC $B6 : BNE .mul_op1_pos : INC $B7
    INC $B8
.mul_op1_pos:
    LDA $B3
    BPL .mul_op2_pos
    ; Negate operand2
    LDA $B2 : EOR #$FF : STA $B2
    LDA $B3 : EOR #$FF : STA $B3
    INC $B2 : BNE .mul_op2_pos : INC $B3
    INC $B8
.mul_op2_pos:
    ; Unsigned multiply: $B6-$B7 x $B2-$B3 -> $B0-$B3
    LDA #$00
    STA $B0
    STA $B1
    STA $B4
    STA $B5
    LDX #16
.mul_loop:
    LSR $B3
    ROR $B2
    BCC .mul_no_add
    CLC
    LDA $B0
    ADC $B6
    STA $B0
    LDA $B1
    ADC $B7
    STA $B1
    LDA $B4
    ADC #$00
    STA $B4
    LDA $B5
    ADC #$00
    STA $B5
.mul_no_add:
    ASL $B6
    ROL $B7
    DEX
    BNE .mul_loop
    ; Apply sign
    LDA $B8
    AND #$01
    BEQ .mul_done
    LDA $B0 : EOR #$FF : STA $B0
    LDA $B1 : EOR #$FF : STA $B1
    INC $B0 : BNE .mul_done : INC $B1
.mul_done:
    ; Return result in A/X
    LDA $B0
    LDX $B1
    RTS
_div16:
    LDA #$00
    STA $B8         ; sign flag
    LDA $B1
    BPL .div16_op1_pos
    ; Negate dividend
    LDA $B0 : EOR #$FF : STA $B0
    LDA $B1 : EOR #$FF : STA $B1
    INC $B0 : BNE .div16_op1_pos : INC $B1
    INC $B8
.div16_op1_pos:
    LDA $B5
    BPL .div16_op2_pos
    ; Negate divisor
    LDA $B4 : EOR #$FF : STA $B4
    LDA $B5 : EOR #$FF : STA $B5
    INC $B4 : BNE .div16_op2_pos : INC $B5
    INC $B8
.div16_op2_pos:
    JSR _udiv16
    ; Apply sign to quotient
    LDA $B8
    AND #$01
    BEQ .div16_done
    LDA $B0 : EOR #$FF : STA $B0
    LDA $B1 : EOR #$FF : STA $B1
    INC $B0 : BNE .div16_done : INC $B1
.div16_done:
    LDA $B0
    LDX $B1
    RTS
_mod16:
    LDA $B1         ; save dividend sign (bit 7)
    PHA
    JSR _div16
    LDA $B2
    LDX $B3
    STA $B0
    STX $B1
    PLA
    BPL .mod16_done
    ; Negate remainder (dividend was negative)
    SEC
    LDA #$00 : SBC $B0 : STA $B0
    LDA #$00 : SBC $B1 : STA $B1
.mod16_done:
    LDA $B0
    LDX $B1
    RTS
_udiv16:
    LDA $B4
    STA $B6
    LDA $B5
    STA $B7
    LDA #$00
    STA $B2
    STA $B3
    LDX #16
.udiv_loop:
    ASL $B0
    ROL $B1
    ROL $B2
    ROL $B3
    SEC
    LDA $B2
    SBC $B6
    TAY
    LDA $B3
    SBC $B7
    BCC .udiv_no_sub
    STY $B2
    STA $B3
    INC $B0
.udiv_no_sub:
    DEX
    BNE .udiv_loop
    RTS
_mul32:
    ; 32-bit signed multiply -> i32Mul (support/generic/asm/i32/i32Mul.asm)
    JSR i32Mul
    RTS
_div32:
    ; 32-bit signed division -> i32Div (support/generic/asm/i32/i32Div.asm)
    JSR i32Div
    RTS
_mod32:
    ; 32-bit signed modulus -> i32Mod (support/generic/asm/i32/i32Mod.asm)
    JSR i32Mod
    RTS

